import { test } from "node:test";
import assert from "node:assert/strict";
import { SessionManager, type RefreshRecord, type RefreshStore } from "../src/auth/sessions.ts";
import { authRoutes } from "../src/auth/routes.ts";

const SECRET = "test-signing-secret";

function setup() {
    const rows = new Map<string, RefreshRecord>();
    const store: RefreshStore = {
        insert: async (r) => void rows.set(r.tokenHash, { ...r }),
        get: async (h) => (rows.has(h) ? { ...rows.get(h)! } : null),
        update: async (r) => void rows.set(r.tokenHash, { ...r }),
        bySession: async (sid) => [...rows.values()].filter((r) => r.sessionId === sid).map((r) => ({ ...r })),
        byUser: async (uid) => [...rows.values()].filter((r) => r.userId === uid).map((r) => ({ ...r })),
    };
    const clock = { t: Date.parse("2026-11-19T10:00:00Z") };
    const sessions = new SessionManager(store, SECRET, () => clock.t);
    const api = authRoutes(sessions, SECRET, () => clock.t);
    const refresh = (token: string) => api.token({ grant_type: "refresh_token", refresh_token: token });
    return { sessions, api, refresh, clock };
}

const refreshTokenOf = (res: { body: unknown }) => (res.body as { refresh_token: string }).refresh_token;

test("signing in gives an access token the playback API accepts", async () => {
    const { sessions, api } = setup();
    const pair = await sessions.start("listener-1", "Living room TV");
    const claims = api.authenticate(`Bearer ${pair.accessToken}`);
    assert.deepEqual([claims?.sub, claims?.sid], ["listener-1", pair.sessionId]);
});

test("refreshing returns a new token pair for the same device session", async () => {
    const { sessions, refresh } = setup();
    const first = await sessions.start("listener-1", "Phone");
    const res = await refresh(first.refreshToken);
    assert.equal(res.status, 200);
    assert.notEqual(refreshTokenOf(res), first.refreshToken);
    assert.equal((await refresh(refreshTokenOf(res))).status, 200);
});

test("a refresh token that has already been exchanged can't be used again", async () => {
    const { sessions, refresh } = setup();
    const first = await sessions.start("listener-1", "Phone");
    await refresh(first.refreshToken);
    const again = await refresh(first.refreshToken);
    assert.deepEqual(again, { status: 401, body: { error: "invalid_grant" } });
});

test("replaying an exchanged refresh token ends that device's session", async () => {
    const { sessions, refresh } = setup();
    const stolen = await sessions.start("listener-1", "Laptop");
    const attacker = await refresh(stolen.refreshToken);
    // the real app later tries the copy it still has
    await refresh(stolen.refreshToken);
    assert.equal((await refresh(refreshTokenOf(attacker))).status, 401);
    assert.deepEqual(await sessions.activeDevices("listener-1"), []);
});

test("after logout the device's refresh token stops working", async () => {
    const { sessions, api, refresh } = setup();
    const pair = await sessions.start("listener-1", "Web player");
    assert.equal((await api.logout({ refresh_token: pair.refreshToken })).status, 204);
    const res = await refresh(pair.refreshToken);
    console.log("refresh after logout:", res.status, res.body);
    assert.equal(res.status, 401);
});

test("a password change signs out every device", async () => {
    const { sessions, refresh } = setup();
    const phone = await sessions.start("listener-1", "Phone");
    const tv = await sessions.start("listener-1", "Living room TV");
    const other = await sessions.start("listener-2", "Phone");
    assert.deepEqual(await sessions.activeDevices("listener-1"), ["Living room TV", "Phone"]);
    await sessions.logoutEverywhere("listener-1");
    assert.deepEqual(await sessions.activeDevices("listener-1"), []);
    assert.deepEqual([(await refresh(phone.refreshToken)).status, (await refresh(tv.refreshToken)).status], [401, 401]);
    assert.equal((await refresh(other.refreshToken)).status, 200);
});

test("expired refresh tokens are rejected", async () => {
    const { sessions, refresh, clock } = setup();
    const pair = await sessions.start("listener-1", "Phone");
    clock.t += 31 * 24 * 60 * 60_000;
    assert.equal((await refresh(pair.refreshToken)).status, 401);
    assert.equal((await refresh("not-a-real-token")).status, 401);
});

test("access tokens that are tampered with or expired are rejected", async () => {
    const { sessions, api, clock } = setup();
    const { accessToken } = await sessions.start("listener-1", "Phone");
    const [payload, sig] = accessToken.split(".");
    const forged = Buffer.from(JSON.stringify({ ...JSON.parse(Buffer.from(payload, "base64url").toString()), sub: "listener-2" })).toString("base64url");
    assert.equal(api.authenticate(`Bearer ${forged}.${sig}`), null);
    clock.t += 6 * 60_000;
    assert.equal(api.authenticate(`Bearer ${accessToken}`), null);
});
